  "pairs": [
    {
      "symbol": "BTC/USDT",
      "bias": "bullish",
      "confidence": 75,
      "note": "BTC is showing significant strength, climbing towards $72,000 despite a risk-off macro environment driven by surging oil prices. This resilience suggests strong crypto-specific demand is currently outweighing broader market fears."
    },
    {
      "symbol": "XAU/USD",
      "bias": "neutral",
      "confidence": 55,
      "note": "Gold is caught between conflicting drivers. While geopolitical tensions provide safe-haven demand, surging oil prices are dampening rate-cut expectations, which supports the dollar and caps gold's upside."
    },
    {
      "symbol": "US100",
      "bias": "bearish",
      "confidence": 70,
      "note": "US equities are under pressure from surging oil prices and escalating geopolitical conflict. The Nasdaq is selling off as investor sentiment turns cautious and fears of sustained energy-driven inflation rise."
    },
    {
      "symbol": "SPX500",
      "bias": "bearish",
      "confidence": 70,
      "note": "The S&P 500 is declining amid broad market sell-offs triggered by the Middle East conflict and its impact on oil prices. The risk-off sentiment is leading investors to exit equity positions."
    }
  ],
  "forex_news": []
}

